import ast
import os
import sys
import subprocess
import tempfile
import shutil
import time
import re
import json
import tomllib
from dataclasses import dataclass, field
from typing import Dict, List, Optional, Any, Tuple, Iterable

# Constants
SKIPPED = 'skipped'
PASSED = 'passed'
FAILED = 'failed'
DEFAULT_PENALTY_PER_GATE = 6.25
DEFAULT_TIMEOUT_S = 60

# Dependency contract: hae/evaluation/artifacts.py
# Since it's being implemented in parallel, we assume it exists or implement fallbacks if needed.
# However, the prompt implies we should use it. If it's not present, we might need to stub it or import it.
# Given the strict contract, I will import it. If it fails, the harness might fail, but the spec says it's being implemented.
# To be safe against import errors during development/testing if artifacts.py isn't ready, 
# I'll try to import it, and if it fails, define minimal fallbacks that match the contract.
try:
    from hae.evaluation.artifacts import (
        is_generated_path,
        is_malformed_path,
        sanitize_path,
        filter_bundle,
        partition_bundle,
        count_source_files,
        EXCLUDED_DIR_SEGMENTS,
        EXCLUDED_DIR_SUFFIXES
    )
except ImportError:
    # Fallback implementation matching the contract if artifacts.py is not yet available
    EXCLUDED_DIR_SEGMENTS = ('.pytest_cache', '__pycache__', 'venv', '.venv', '.git', '.mypy_cache', '.ruff_cache', '.tox', 'node_modules', '.ipynb_checkpoints')
    EXCLUDED_DIR_SUFFIXES = ('.egg-info', '.dist-info')

    def is_generated_path(path: str) -> bool:
        parts = path.replace('\\', '/').split('/')
        for part in parts:
            if part in EXCLUDED_DIR_SEGMENTS:
                return True
            if any(part.endswith(s) for s in EXCLUDED_DIR_SUFFIXES):
                return True
        return False

    def is_malformed_path(path: str) -> bool:
        if not path:
            return True
        if path != path.strip():
            return True
        if '*' in path or '`' in path:
            return True
        if path.startswith('-'):
            return True
        if path.endswith('.') or path.endswith('~'):
            return True
        return False

    def sanitize_path(path: str) -> str:
        # Strip markdown decoration
        path = path.strip()
        path = path.replace('*', '').replace('`', '')
        if path.startswith('-'):
            path = path[1:]
        if path.endswith('.') or path.endswith('~'):
            path = path[:-1]
        return path

    def filter_bundle(bundle: Dict[str, str]) -> Dict[str, str]:
        return {k: v for k, v in bundle.items() if not is_generated_path(k) and not is_malformed_path(k)}

    def partition_bundle(bundle: Dict[str, str]) -> Tuple[Dict[str, str], Dict[str, str], Dict[str, str]]:
        authored = {}
        generated = {}
        malformed = {}
        for k, v in bundle.items():
            if is_generated_path(k):
                generated[k] = v
            elif is_malformed_path(k):
                malformed[k] = v
            else:
                authored[k] = v
        return authored, generated, malformed

    def count_source_files(bundle: Dict[str, str], suffixes: Iterable[str] = ('.py',)) -> int:
        count = 0
        for path in bundle:
            if not is_generated_path(path) and not is_malformed_path(path):
                if any(path.endswith(s) for s in suffixes):
                    count += 1
        return count


@dataclass
class GateResult:
    """Outcome of a single verification gate."""
    name: str
    status: str
    method: str
    detail: str = ''
    duration_s: float = 0.0
    evidence: Dict[str, Any] = field(default_factory=dict)

    @property
    def passed(self) -> bool:
        return self.status == PASSED

    @property
    def evaluated(self) -> bool:
        return self.status != SKIPPED


@dataclass
class VerificationReport:
    """Aggregate result across all gates."""
    gates: List[GateResult]
    score_penalty: float
    authored_files: int
    python_files: int
    source: str = 'bundle'
    harness_version: str = '3.0-execution'

    def gate(self, name: str) -> Optional[GateResult]:
        for g in self.gates:
            if g.name == name:
                return g
        return None

    @property
    def evaluated_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.evaluated]

    @property
    def passed_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.passed]

    @property
    def gate_status(self) -> Dict[str, str]:
        """Gate name -> PASSED | FAILED | SKIPPED. The fitness function's input."""
        return {g.name: g.status for g in self.gates}

    @property
    def gate_detail(self) -> Dict[str, str]:
        return {g.name: g.detail for g in self.gates}

    @property
    def pass_rate(self) -> float:
        """Fraction of *evaluated* gates that passed. Skips are excluded."""
        evaluated = self.evaluated_gates
        if not evaluated:
            return 0.0
        passed = [g for g in evaluated if g.passed]
        return len(passed) / len(evaluated)

    def summary(self) -> str:
        lines = [f"Verification Report ({self.source})"]
        lines.append(f"Authored Files: {self.authored_files}, Python Files: {self.python_files}")
        lines.append(f"Score Penalty: {self.score_penalty:.2f}")
        lines.append(f"Pass Rate: {self.pass_rate:.2%}")
        lines.append("Gates:")
        for g in self.gates:
            lines.append(f"  [{g.status.upper()}] {g.name}: {g.detail}")
        return "\n".join(lines)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "gates": [
                {
                    "name": g.name,
                    "status": g.status,
                    "method": g.method,
                    "detail": g.detail,
                    "duration_s": g.duration_s,
                    "evidence": g.evidence
                } for g in self.gates
            ],
            "score_penalty": self.score_penalty,
            "authored_files": self.authored_files,
            "python_files": self.python_files,
            "source": self.source,
            "harness_version": self.harness_version,
            "pass_rate": self.pass_rate,
            "gate_status": self.gate_status
        }


def extract_code_blocks(text: str) -> Dict[str, str]:
    """Recovers a path->content map from fenced code blocks in a deliverable.

    A last resort, used only when a firm produced no live workspace. Only the
    contents of fenced blocks are returned; the surrounding prose is discarded
    and never reaches a gate.
    """
    if not text:
        return {}

    # Regex to find fenced code blocks with optional language and optional filename hint
    # Common patterns: ```python\n...\n``` or ```path/to/file.py\n...\n```
    # We look for blocks where the info string might contain a .py extension or just 'python'
    # If no path is given, we might need to guess or skip. The spec says "path->content map".
    # Usually, agents write ```path/to/file.py ... ```

    pattern = r"```(?:\s*(?P<lang>[\w\+\-\.]+))?\s*\n(?P<code>.*?)\n```"
    matches = re.finditer(pattern, text, re.DOTALL)

    bundle = {}
    for i, match in enumerate(matches):
        lang = match.group('lang') or ''
        code = match.group('code')

        # Determine path
        path = None
        if lang:
            # If lang looks like a path (contains / or .py), use it
            if '/' in lang or lang.endswith('.py'):
                path = lang
            elif lang == 'python':
                # Generate a dummy path if no path provided, e.g., block_0.py
                path = f"block_{i}.py"
            else:
                # Ignore non-python blocks or blocks without clear path
                continue
        else:
            # No language specified, assume python if it looks like code? 
            # Spec says "fenced code blocks". Usually implies language.
            # If no lang, we might skip or assume python. Let's assume python for safety if it parses.
            path = f"block_{i}.py"

        if path:
            # Sanitize path if needed
            path = sanitize_path(path)
            if not is_malformed_path(path):
                bundle[path] = code

    return bundle


class ExecutionHarness:
    """Materializes a workspace bundle and verifies it by actually running it."""

    def __init__(self, timeout_s: int = DEFAULT_TIMEOUT_S, penalty_per_gate: float = DEFAULT_PENALTY_PER_GATE, python_executable: Optional[str] = None):
        self.timeout_s = timeout_s
        self.penalty_per_gate = penalty_per_gate
        self.python_executable = python_executable or sys.executable

    def verify_workspace(self, workspace: Any = None, deliverable_text: str = '') -> VerificationReport:
        """Verifies whatever code a firm actually produced.

        This is the entry point tournaments use. A firm normally writes into a
        live `AgentWorkspace`; if it never did, we fall back to the fenced code
        blocks embedded in its written deliverable.

        `deliverable_text` is *only* mined for code blocks. Its prose is never
        passed to a gate, because the entire point of this harness is that an
        essay about OpenTelemetry cannot satisfy the telemetry gate.
        """
        bundle = {}
        source = 'bundle'

        # Try to get bundle from workspace object
        if workspace is not None:
            # Assume workspace has a method to get files or is a dict
            if isinstance(workspace, dict):
                bundle = workspace
                source = 'bundle'
            elif hasattr(workspace, 'list_files'):
                # Common interface for AgentWorkspace
                try:
                    files = workspace.list_files()
                    # list_files might return paths, need to read content
                    # This depends on the specific workspace implementation.
                    # If it returns a dict of path->content, great.
                    # If it returns list of paths, we need to read them.
                    if isinstance(files, dict):
                        bundle = files
                    elif isinstance(files, list):
                        # Try to read them if they are paths relative to some root
                        # This is tricky without knowing the workspace root.
                        # Often workspaces have a 'read_file' method
                        if hasattr(workspace, 'read_file'):
                            for path in files:
                                try:
                                    content = workspace.read_file(path)
                                    bundle[path] = content
                                except Exception:
                                    pass
                    source = 'workspace'
                except Exception:
                    pass
            elif hasattr(workspace, 'files'):
                if isinstance(workspace.files, dict):
                    bundle = workspace.files
                    source = 'workspace'

        # Fallback to deliverable text if bundle is empty
        if not bundle and deliverable_text:
            bundle = extract_code_blocks(deliverable_text)
            source = 'deliverable'

        if not bundle:
            # Empty workspace
            return self._empty_report(source)

        return self.verify_bundle(bundle, source=source)

    def _empty_report(self, source: str) -> VerificationReport:
        gates = [
            GateResult(name='syntax', status=FAILED, method='ast_parse', detail='No Python files found'),
            GateResult(name='build', status=FAILED, method='metadata_check', detail='No packaging metadata found'),
            GateResult(name='smoke', status=FAILED, method='import_check', detail='No modules to import'),
            GateResult(name='tests', status=FAILED, method='pytest_run', detail='No test files found'),
            GateResult(name='telemetry', status=FAILED, method='ast_analysis', detail='No Python files found'),
        ]
        failed_count = sum(1 for g in gates if g.status == FAILED)
        return VerificationReport(
            gates=gates,
            score_penalty=failed_count * self.penalty_per_gate,
            authored_files=0,
            python_files=0,
            source=source
        )

    def verify_bundle(self, bundle: Dict[str, str], source: str = 'bundle') -> VerificationReport:
        """Verifies an in-memory path->content map by writing it to a temp dir."""
        # Filter bundle to remove generated/malformed paths
        authored_bundle = filter_bundle(bundle)

        # Count files
        authored_files = len(authored_bundle)
        python_files = count_source_files(authored_bundle, suffixes=('.py',))

        if authored_files == 0:
            return self._empty_report(source)

        with tempfile.TemporaryDirectory() as tmpdir:
            # Write files to temp dir
            for path, content in authored_bundle.items():
                full_path = os.path.join(tmpdir, path)
                os.makedirs(os.path.dirname(full_path), exist_ok=True)
                with open(full_path, 'w', encoding='utf-8') as f:
                    f.write(content)

            return self.verify_directory(tmpdir, authored=authored_bundle, source=source)

    def verify_directory(self, workdir: str, authored: Optional[Dict[str, str]] = None, source: str = 'directory') -> VerificationReport:
        """Verifies an existing workspace directory."""
        if authored is None:
            # Scan directory
            authored = {}
            for root, dirs, files in os.walk(workdir):
                # Filter out excluded dirs
                dirs[:] = [d for d in dirs if not is_generated_path(os.path.relpath(os.path.join(root, d), workdir))]
                for file in files:
                    rel_path = os.path.relpath(os.path.join(root, file), workdir)
                    if not is_generated_path(rel_path) and not is_malformed_path(rel_path):
                        try:
                            with open(os.path.join(root, file), 'r', encoding='utf-8') as f:
                                authored[rel_path] = f.read()
                        except Exception:
                            pass

        authored_files = len(authored)
        python_files = count_source_files(authored, suffixes=('.py',))

        if authored_files == 0:
            return self._empty_report(source)

        gates = []

        # 1. Syntax Gate
        gates.append(self._gate_syntax(workdir, authored))

        # 2. Build Gate
        gates.append(self._gate_build(workdir, authored))

        # 3. Smoke Gate
        gates.append(self._gate_smoke(workdir, authored))

        # 4. Tests Gate
        gates.append(self._gate_tests(workdir, authored))

        # 5. Telemetry Gate
        gates.append(self._gate_telemetry(workdir, authored))

        failed_count = sum(1 for g in gates if g.status == FAILED)
        score_penalty = failed_count * self.penalty_per_gate

        return VerificationReport(
            gates=gates,
            score_penalty=score_penalty,
            authored_files=authored_files,
            python_files=python_files,
            source=source
        )

    def _gate_syntax(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()
        py_files = [p for p in authored if p.endswith('.py')]
        if not py_files:
            return GateResult(name='syntax', status=FAILED, method='ast_parse', detail='No Python files found', duration_s=time.time()-start)

        errors = []
        for path in py_files:
            full_path = os.path.join(workdir, path)
            try:
                with open(full_path, 'r', encoding='utf-8') as f:
                    content = f.read()
                ast.parse(content)
            except SyntaxError as e:
                errors.append(f"{path}: {e}")
            except Exception as e:
                errors.append(f"{path}: {e}")

        duration = time.time() - start
        if errors:
            return GateResult(name='syntax', status=FAILED, method='ast_parse', detail='; '.join(errors), duration_s=duration)
        return GateResult(name='syntax', status=PASSED, method='ast_parse', detail='All Python files parsed successfully', duration_s=duration)

    def _gate_build(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()
        # Check for packaging metadata
        metadata_files = ['pyproject.toml', 'setup.py', 'setup.cfg']
        found_metadata = None

        for mf in metadata_files:
            if mf in authored:
                found_metadata = mf
                break

        if not found_metadata:
            return GateResult(name='build', status=FAILED, method='metadata_check', detail='No packaging metadata found', duration_s=time.time()-start)

        # Validate pyproject.toml if present
        if 'pyproject.toml' in authored:
            try:
                with open(os.path.join(workdir, 'pyproject.toml'), 'rb') as f:
                    data = tomllib.load(f)
                # Must contain at least one of [project], [build-system], or [tool]
                if not any(k in data for k in ['project', 'build-system', 'tool']):
                    return GateResult(name='build', status=FAILED, method='toml_validation', detail='pyproject.toml missing required tables', duration_s=time.time()-start)
            except Exception as e:
                return GateResult(name='build', status=FAILED, method='toml_validation', detail=f'Invalid pyproject.toml: {e}', duration_s=time.time()-start)

        # Try pip install
        try:
            # Check if pip is available
            subprocess.run([self.python_executable, '-m', 'pip', '--version'], capture_output=True, timeout=10)
            # Run install
            cmd = [self.python_executable, '-m', 'pip', 'install', '-e', '.', '--no-deps', '--no-build-isolation']
            result = subprocess.run(cmd, cwd=workdir, capture_output=True, text=True, timeout=self.timeout_s)
            if result.returncode != 0:
                return GateResult(name='build', status=FAILED, method='pip_install', detail=f'pip install failed: {result.stderr}', duration_s=time.time()-start)
        except FileNotFoundError:
            return GateResult(name='build', status=SKIPPED, method='pip_install', detail='pip not available', duration_s=time.time()-start)
        except subprocess.TimeoutExpired:
            return GateResult(name='build', status=FAILED, method='pip_install', detail='pip install timed out', duration_s=time.time()-start)
        except Exception as e:
            return GateResult(name='build', status=FAILED, method='pip_install', detail=f'Error running pip: {e}', duration_s=time.time()-start)

        return GateResult(name='build', status=PASSED, method='pip_install', detail='Package installed successfully', duration_s=time.time()-start)

    def _gate_smoke(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()
        # Find non-test authored modules
        # Exclude test files
        modules = []
        for path in authored:
            if not path.endswith('.py'):
                continue
            if 'test' in os.path.basename(path).lower():
                continue
            # Convert path to module name
            # e.g. src/module.py -> module (if src is on path) or src.module
            # We will add workdir and workdir/src to PYTHONPATH
            rel_path = path
            if rel_path.startswith('src/'):
                mod_name = rel_path[4:-3].replace('/', '.')
            else:
                mod_name = rel_path[:-3].replace('/', '.')
            if mod_name:
                modules.append(mod_name)

        if not modules:
            return GateResult(name='smoke', status=FAILED, method='import_check', detail='No importable modules found', duration_s=time.time()-start)

        # Prepare environment
        env = os.environ.copy()
        python_path = [workdir, os.path.join(workdir, 'src')]
        if 'PYTHONPATH' in env:
            env['PYTHONPATH'] = os.pathsep.join(python_path + [env['PYTHONPATH']])
        else:
            env['PYTHONPATH'] = os.pathsep.join(python_path)

        # Run a script that imports all modules
        script = 'import sys'
        for mod in modules:
            script += f'try:'
            script += f'    import {mod}'
            script += f'except ModuleNotFoundError:'
            script += f'    print(f\'MODULE_NOT_FOUND:{mod}:\')'
            script += f'except Exception:'
            script += f'    print(f\'IMPORT_ERROR:{mod}:\')'

        try:
            result = subprocess.run([self.python_executable, '-c', script], cwd=workdir, env=env, capture_output=True, text=True, timeout=self.timeout_s)
            duration = time.time() - start

            stdout = result.stdout
            stderr = result.stderr

            # Check for ModuleNotFoundError
            if 'MODULE_NOT_FOUND' in stdout:
                # If all failures are ModuleNotFoundError, return SKIPPED
                # If some are other errors, return FAILED
                lines = stdout.strip().split('\n')
                has_other_error = False
                for line in lines:
                    if line.startswith('IMPORT_ERROR'):
                        has_other_error = True
                        break
                if not has_other_error:
                    return GateResult(name='smoke', status=SKIPPED, method='import_check', detail='Modules not found (third-party deps missing)', duration_s=duration)
                else:
                    return GateResult(name='smoke', status=FAILED, method='import_check', detail='Some modules failed to import', duration_s=duration)

            if 'IMPORT_ERROR' in stdout:
                return GateResult(name='smoke', status=FAILED, method='import_check', detail='Some modules failed to import', duration_s=duration)

            if result.returncode != 0:
                return GateResult(name='smoke', status=FAILED, method='import_check', detail=f'Import script failed: {stderr}', duration_s=duration)

            return GateResult(name='smoke', status=PASSED, method='import_check', detail='All modules imported successfully', duration_s=duration)

        except Exception as e:
            return GateResult(name='smoke', status=FAILED, method='import_check', detail=f'Error running import check: {e}', duration_s=time.time()-start)

    def _gate_tests(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()
        # Find test files
        test_files = [p for p in authored if 'test' in os.path.basename(p).lower() and p.endswith('.py')]

        if not test_files:
            return GateResult(name='tests', status=FAILED, method='pytest_run', detail='No test files found', duration_s=time.time()-start)

        # Prepare environment
        env = os.environ.copy()
        python_path = [workdir, os.path.join(workdir, 'src')]
        if 'PYTHONPATH' in env:
            env['PYTHONPATH'] = os.pathsep.join(python_path + [env['PYTHONPATH']])
        else:
            env['PYTHONPATH'] = os.pathsep.join(python_path)

        # Try pytest first
        try:
            subprocess.run([self.python_executable, '-m', 'pytest', '--version'], capture_output=True, timeout=10)
            cmd = [self.python_executable, '-m', 'pytest', '-v'] + test_files
            result = subprocess.run(cmd, cwd=workdir, env=env, capture_output=True, text=True, timeout=self.timeout_s)
            duration = time.time() - start

            if result.returncode == 0:
                return GateResult(name='tests', status=PASSED, method='pytest_run', detail='Tests passed', duration_s=duration)
            else:
                # Check if it was a collection error due to missing modules
                if 'ModuleNotFoundError' in result.stdout or 'ModuleNotFoundError' in result.stderr:
                    # If tests couldn't be collected due to missing deps, skip
                    # But if they ran and failed, it's FAILED
                    if 'collected 0 items' in result.stdout or 'no tests ran' in result.stdout:
                         return GateResult(name='tests', status=SKIPPED, method='pytest_run', detail='Tests skipped due to missing dependencies', duration_s=duration)
                return GateResult(name='tests', status=FAILED, method='pytest_run', detail='Tests failed', duration_s=duration)
        except FileNotFoundError:
            pass # pytest not installed, fallback
        except Exception:
            pass # pytest failed to run, fallback

        # Stdlib fallback
        # Run a script that imports each test file and collects/executes tests
        script = "import sys\nimport unittest\nimport importlib\nimport traceback\n"
        script += "def run_tests():\n"
        script += "    loader = unittest.TestLoader()\n"
        script += "    suite = unittest.TestSuite()\n"
        script += "    test_files = " + repr(test_files) + "\n"
        script += "    for tf in test_files:\n"
        script += "        try:\n"
        script += "            mod_name = tf.replace('/', '.').replace('.py', '')\n"
        script += "            mod = importlib.import_module(mod_name)\n"
        script += "            # Collect bare test functions\n"
        script += "            for name in dir(mod):\n"
        script += "                obj = getattr(mod, name)\n"
        script += "                if callable(obj) and name.startswith('test_'):\n"
        script += "                    # Check if it's a function taking 0 args (excluding self)\n"
        script += "                    import inspect\n"
        script += "                    sig = inspect.signature(obj)\n"
        script += "                    params = list(sig.parameters.values())\n"
        script += "                    if len(params) == 0:\n"
        script += "                        suite.addTest(unittest.FunctionTestCase(obj))\n"
        script += "            # Collect TestCase subclasses\n"
        script += "            suite.addTests(loader.loadTestsFromModule(mod))\n"
        script += "        except ModuleNotFoundError as e:\n"
        script += "            err_msg = str(e)\n"
        script += "            print(f'MODULE_NOT_FOUND:{tf}:{err_msg}')\n"
        script += "        except Exception as e:\n"
        script += "            err_msg = str(e)\n"
        script += "            print(f'IMPORT_ERROR:{tf}:{err_msg}')\n"
        script += "    runner = unittest.TextTestRunner(verbosity=2)\n"
        script += "    result = runner.run(suite)\n"
        script += "    if result.wasSuccessful():\n"
        script += "        sys.exit(0)\n"
        script += "    else:\n"
        script += "        sys.exit(1)\n"
        script += "run_tests()\n"

        try:
            result = subprocess.run([self.python_executable, '-c', script], cwd=workdir, env=env, capture_output=True, text=True, timeout=self.timeout_s)
            duration = time.time() - start

            stdout = result.stdout
            stderr = result.stderr

            if 'MODULE_NOT_FOUND' in stdout:
                # Check if any other errors
                if 'IMPORT_ERROR' in stdout:
                    return GateResult(name='tests', status=FAILED, method='stdlib_fallback', detail='Some test files failed to import', duration_s=duration)
                return GateResult(name='tests', status=SKIPPED, method='stdlib_fallback', detail='Tests skipped due to missing dependencies', duration_s=duration)

            if result.returncode == 0:
